		// track whether we found an escape '\' for the next
		// iteration to be contextually aware
		if !escaped {
			if !btQuoted {
				if ch == '\\' {
					escaped = true
					continue
				}
			}
		}

		if quoted {
			if escaped {
				if ch != '"' {
					val = append(val, '\\')
				}
				escaped = false
			} else {
				if ch == '"' {
					return makeToken(ch), nil
				}
			}
			if ch == '\n' {
				consumed := 1 + l.skippedLines
				l.line += consumed
				l.skippedLines = 0
			}
			quotedChar := ch
			val = append(val, quotedChar)
			continue
